CREATE FUNCTION trg_stock() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE products
  SET stock_quantity = stock_quantity - NEW.quantity
  WHERE product_id = NEW.product_id;
  RETURN NEW;
END; $$;

CREATE TRIGGER items_stock AFTER INSERT
ON order_items FOR EACH ROW
EXECUTE FUNCTION trg_stock();

